


/** Buyer contact supplied with payment or saved during checkout. */ export type CheckoutBuyerContactInput = { /** Email supplied for the buyer, exactly as sent. Null when no email is saved; is_email_cleared distinguishes an explicit clear. Format: email. maxLength: 255. */ "email": string | null; /** True when the buyer explicitly cleared the email, including before entering one. Saving an email resets it to false. Do not restore a prefilled email while true. */ "is_email_cleared"?: never; /** True when the buyer explicitly cleared the phone, including before entering one. Saving a phone resets it to false. Do not restore a prefilled phone while true. */ "is_phone_cleared"?: never; /** Phone supplied for the buyer, in E.164 format. Null when no phone is saved; is_phone_cleared distinguishes an explicit clear. pattern: ^\+[1-9][0-9]{1,14}$. */ "phone": string | null; /** When the buyer last changed the saved checkout contact. Omitted on order buyer contact. Format: date-time. */ "updated_at"?: never; };
